DROP DATABASE IF EXISTS creditsuisse;
CREATE DATABASE creditSuisse;
USE creditSuisse;

-- TABELLEN 

-- Fuer die Darstelllung des Aktienkurses
CREATE TABLE aktienkurs (
	datum  DATE PRIMARY KEY,
    kurs numeric(10,2) NOT NULL 
);

-- Credit Suisse Aktienkurs in CHF (nominal), Monatswerte
